const tok = input.trim().split(/\s+/);
let pos = 0;
const nextInt = () => parseInt(tok[pos++], 10);
const r = nextInt(), c = nextInt();
const g = [];
for (let i = 0; i < r; i++) {
  const row = [];
  for (let j = 0; j < c; j++) row.push(nextInt());
  g.push(row);
}
const q = nextInt();
const out = [];
for (let t = 0; t < q; t++) {
  const x = nextInt();
  let lo = 0, hi = r * c - 1, found = false;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    const v = g[Math.floor(mid / c)][mid % c];
    if (v === x) { found = true; break; }
    if (v < x) lo = mid + 1; else hi = mid - 1;
  }
  out.push(found ? "YES" : "NO");
}
